# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), ключ сверен с ответами учебника (№224: «2) вторая; 4) четвёртая; 6) вторая») и вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_18_224_2", r"$2\frac23\pi=\frac{8\pi}{3}=2\pi+\frac{2\pi}{3}$, остаток $\frac{2\pi}{3}$ ($120^{\circ}$) — вторая четверть (ответ учебника: «2) вторая четверть»); в ключе стояло III, а верный ответ II был среди дистракторов",
  k=r"$II$",
  dnew={0: (r"$I$", r"Ученик вычел полный оборот $2\pi$, но остаток $\frac{2\pi}{3}$ записал как $\frac{\pi}{3}$ (потерял множитель $2$) и отнёс угол к первой четверти."),
        1: (r"$III$", r"Ученик вычел $2\pi$ и получил $\frac{2\pi}{3}$, но отложил этот угол по часовой стрелке (как $-\frac{2\pi}{3}$), то есть в третьей четверти."),
        2: (r"$IV$", r"Ученик вычел один $\pi$ вместо полного оборота $2\pi$: $2\frac23\pi-\pi=1\frac23\pi=\frac{5\pi}{3}$ — четвёртая четверть; верно вычитать $2\pi$.")})
E("G9_TB_18_224_3", r"$-\frac{13\pi}{3}=-4\pi-\frac{\pi}{3}$, эквивалентно $-\frac{\pi}{3}$ ($-60^{\circ}$, поворот по часовой стрелке) — четвёртая четверть; в ключе стояло III, а верный ответ IV был среди дистракторов",
  k=r"$IV$",
  dnew={0: (r"$I$", r"Ученик отбросил знак минус: $\frac{13\pi}{3}-4\pi=\frac{\pi}{3}$ — первая четверть; но угол отрицательный, поворот идёт по часовой стрелке."),
        1: (r"$II$", r"Ученик привёл угол к $-\frac{\pi}{3}$, но отложил $\frac{\pi}{3}$ от отрицательного направления оси $Ox$ (получил $\pi-\frac{\pi}{3}=\frac{2\pi}{3}$) — вторая четверть."),
        2: (r"$III$", r"Ученик привёл угол к $-\frac{\pi}{3}$, но отложил его как $\pi+\frac{\pi}{3}$ (перепутал поворот на $-\frac{\pi}{3}$ с поворотом на $\frac{4\pi}{3}$) — третья четверть.")})
